-- Catalog references are shared. Inventory quantities, owners and store SKUs stay in upsoled_products.
create table if not exists public.shoe_catalog_models (
    slug text primary key,
    title text not null check (length(trim(title)) > 0),
    brand text,
    style_code text,
    image_url text,
    size_system text check (size_system in ('us_m', 'us_w', 'us_y')),
    source_url text
);

create table if not exists public.shoe_catalog_variants (
    gtin text primary key check (gtin ~ '^[0-9]{14}$' and gtin <> '00000000000000'),
    model_slug text not null references public.shoe_catalog_models(slug),
    us_size text not null check (us_size ~ '^[0-9]{1,2}([.]5)?Y?$'),
    source_url text not null check (source_url like 'https://%')
);

create index if not exists shoe_catalog_variants_model_slug_idx on public.shoe_catalog_variants (model_slug);
alter table public.shoe_catalog_models enable row level security;
alter table public.shoe_catalog_variants enable row level security;

revoke all on public.shoe_catalog_models, public.shoe_catalog_variants from anon, authenticated;
grant select on public.shoe_catalog_models, public.shoe_catalog_variants to anon, authenticated;
grant select, insert, update, delete on public.shoe_catalog_models, public.shoe_catalog_variants to service_role;
do $policies$
begin
    if not exists (select from pg_policies where schemaname = 'public' and tablename = 'shoe_catalog_models' and policyname = 'Read shared shoe catalog') then
        create policy "Read shared shoe catalog" on public.shoe_catalog_models for select to anon, authenticated using (true);
    end if;
    if not exists (select from pg_policies where schemaname = 'public' and tablename = 'shoe_catalog_variants' and policyname = 'Read shared shoe barcodes') then
        create policy "Read shared shoe barcodes" on public.shoe_catalog_variants for select to anon, authenticated using (true);
    end if;
end;
$policies$;

select slug, name, brand, coalesce(nullif(main_image_url, ''), nullif(image, ''))
from public.upsoled_products
where category = 'shoes'
  and user_id is null
  and organization_id is null
  and length(trim(name)) > 0
on conflict (slug) do nothing;

-- Public footwear references from the repository's Sneak Peek catalog export.
-- The current Uniclick catalog has priority when a slug already exists.
on conflict (slug) do nothing;

     'DZ5485-612', 'https://cdn.snkrdunk.com/upload_bg_removed/20221012010050-0.webp?size=l',
     'us_m', 'https://supplyblog.stadiumgoods.com/2022/11/19/air-jordan-1-chicago-lost-and-found-seller-promo/'),
    ('asics-gel-1130-black-graphite-grey', 'ASICS Gel-1130 Black Graphite Grey', 'ASICS',
     '1201A256-002', null, 'us_m', 'https://www.asics.com/it/en-it/gel-1130/p/1201A256-002.html')
on conflict (slug) do update
set style_code = excluded.style_code,
    size_system = excluded.size_system,
    source_url = excluded.source_url,
    image_url = coalesce(excluded.image_url, shoe_catalog_models.image_url);

